changeSet.sql:
CREATE TABLE bng.baseline_red_line (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL UNIQUE
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    geom geometry(MultiPolygon, 27700) NOT NULL
);

CREATE INDEX idx_baseline_red_line_geom
    ON bng.baseline_red_line USING GIST (geom);

CREATE TABLE bng.baseline_habitats (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiPolygon, 27700) NOT NULL
);

CREATE INDEX idx_baseline_habitats_project_id
    ON bng.baseline_habitats (project_id);

CREATE INDEX idx_baseline_habitats_geom
    ON bng.baseline_habitats USING GIST (geom);

CREATE TABLE bng.baseline_hedgerows (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiLineString, 27700) NOT NULL
);

CREATE INDEX idx_baseline_hedgerows_project_id
    ON bng.baseline_hedgerows (project_id);

CREATE INDEX idx_baseline_hedgerows_geom
    ON bng.baseline_hedgerows USING GIST (geom);

CREATE TABLE bng.baseline_watercourses (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid NOT NULL
        REFERENCES bng.projects(id) ON DELETE CASCADE,
    ref text,
    geom geometry(MultiLineString, 27700) NOT NULL
);

CREATE INDEX idx_baseline_watercourses_project_id
    ON bng.baseline_watercourses (project_id);

CREATE INDEX idx_baseline_watercourses_geom
    ON bng.baseline_watercourses USING GIST (geom);
